import warp as wpfrom . import mathfrom . import constraintfrom . import collision_driverfrom . import smooth_accfrom . import smooth_posfrom . import smooth_musclefrom . import smooth_equilibriumfrom . import smooth_velfrom . import smooth_frcfrom . import smooth_hunt_crossleyfrom . import solverfrom .consts import MJ_MINVALfrom .types import ContactTypefrom .types import Datafrom .types import JointTypefrom .types import Modelfrom .types import TileSetfrom .types import MuscleMetadatafrom .warp_util import cache_kernelfrom .warp_util import event_scopefrom .warp_util import kernel as nested_kernelwp.set_module_options({"enable_backward": False})@wp.kerneldef _next_position(        # Model:        jnt_type: wp.array(dtype=int),        jnt_qposadr: wp.array(dtype=int),        jnt_dofadr: wp.array(dtype=int),        jnt_dofnum: wp.array(dtype=int),        # Data in:        qpos_in: wp.array2d(dtype=float),        qvel_in: wp.array2d(dtype=float),        actual_step_size_in: wp.array(dtype=float),        # In:        scale: float,        # Data out:        qpos_out: wp.array2d(dtype=float),):    worldid, bodyid = wp.tid()    timestep = actual_step_size_in[worldid] * scale    jnttype = jnt_type[bodyid]    qpos_adr = jnt_qposadr[bodyid]    dof_adr = jnt_dofadr[bodyid]    qpos = qpos_in[worldid]    qpos_next = qpos_out[worldid]    qvel = qvel_in[worldid]    if jnttype == JointType.FREE:        qpos_pos = wp.vec3(qpos[qpos_adr], qpos[qpos_adr + 1],                           qpos[qpos_adr + 2])        qvel_lin = wp.vec3(qvel[dof_adr], qvel[dof_adr + 1], qvel[dof_adr + 2])        qpos_new = qpos_pos + timestep * qvel_lin        qpos_quat = wp.quat(            qpos[qpos_adr + 3],            qpos[qpos_adr + 4],            qpos[qpos_adr + 5],            qpos[qpos_adr + 6],        )        qvel_ang = wp.vec3(qvel[dof_adr + 3], qvel[dof_adr + 4],                           qvel[dof_adr + 5])        qpos_quat_new = math.quat_integrate(qpos_quat, qvel_ang, timestep)        qpos_next[qpos_adr + 0] = qpos_new[0]        qpos_next[qpos_adr + 1] = qpos_new[1]        qpos_next[qpos_adr + 2] = qpos_new[2]        qpos_next[qpos_adr + 3] = qpos_quat_new[0]        qpos_next[qpos_adr + 4] = qpos_quat_new[1]        qpos_next[qpos_adr + 5] = qpos_quat_new[2]        qpos_next[qpos_adr + 6] = qpos_quat_new[3]    elif jnttype == JointType.BALL:        qpos_quat = wp.quat(qpos[qpos_adr + 0], qpos[qpos_adr + 1],                            qpos[qpos_adr + 2], qpos[qpos_adr + 3])        qvel_ang = wp.vec3(qvel[dof_adr], qvel[dof_adr + 1], qvel[dof_adr + 2])        qpos_quat_new = math.quat_integrate(qpos_quat, qvel_ang, timestep)        qpos_next[qpos_adr + 0] = qpos_quat_new[0]        qpos_next[qpos_adr + 1] = qpos_quat_new[1]        qpos_next[qpos_adr + 2] = qpos_quat_new[2]        qpos_next[qpos_adr + 3] = qpos_quat_new[3]    elif jnttype == JointType.SLIDE or jnttype == JointType.PIN:        qpos_next[qpos_adr] = qpos[qpos_adr] + timestep * qvel[dof_adr]    elif jnttype == JointType.UNIVERSAL:        qpos_next[qpos_adr] = qpos[qpos_adr] + timestep * qvel[dof_adr]        qpos_next[qpos_adr + 1] = qpos[qpos_adr + 1] + timestep * qvel[            dof_adr + 1]    elif jnttype == JointType.CUSTOM:        num_dofs = jnt_dofnum[bodyid]        dof_adr = jnt_dofadr[bodyid]        for i in range(num_dofs):            qpos_adr_i = qpos_adr + i            dof_adr_i = dof_adr + i            qpos_next[qpos_adr_i] = qpos[qpos_adr_i] + timestep * qvel[                dof_adr_i]    elif jnttype == JointType.DUMMY:        return    else:        assert False@wp.kerneldef _next_velocity(        # Data in:        qvel_in: wp.array2d(dtype=float),        qacc_in: wp.array2d(dtype=float),        actual_step_size_in: wp.array(dtype=float),        # In:        scale: float,        # Data out:        qvel_out: wp.array2d(dtype=float),):    worldid, dofid = wp.tid()    timestep = actual_step_size_in[worldid] * scale    qvel_out[worldid, dofid] = (qvel_in[worldid, dofid] +                                qacc_in[worldid, dofid] * timestep)@wp.kerneldef _next_muscle_state(        # Model:        muscle_metadata: wp.array(dtype=MuscleMetadata),        # Data in:        act_in: wp.array2d(dtype=float),        act_dot_in: wp.array2d(dtype=float),        mstate_in: wp.array2d(dtype=float),        mstate_dot_in: wp.array2d(dtype=float),        actual_step_size_in: wp.array(dtype=float),        # In:        scale: float,        # Data out:        act_out: wp.array2d(dtype=float),        mstate_out: wp.array2d(dtype=float),):    worldid, muscle_id = wp.tid()    mm = muscle_metadata[muscle_id]    step_size = actual_step_size_in[worldid] * scale    # advance muscle activation    act = act_in[worldid, muscle_id] + act_dot_in[        worldid, muscle_id] * step_size    act_out[worldid, muscle_id] = wp.clamp(act, mm.min_activation,                                           mm.max_activation)    # advance muscle state    mstate = mstate_in[worldid, muscle_id] + mstate_dot_in[        worldid, muscle_id] * step_size    mstate_out[worldid, muscle_id] = wp.clamp(mstate, mm.min_norm_fiber_length,                                              mm.max_norm_fiber_length)@wp.kerneldef _next_time(        # Data in:        time_in: wp.array(dtype=float),        actual_step_size_in: wp.array(dtype=float),        # In:        scale: float,        # Data out:        time_out: wp.array(dtype=float),):    worldid = wp.tid()    step_size = actual_step_size_in[worldid] * scale    time_out[worldid] = time_in[worldid] + step_sizedef _advance(m: Model, d: Data, scale: float):    """Advance state and time given state derivatives"""    wp.launch(        _next_muscle_state,        dim=(d.nworld, m.nmuscle),        inputs=[m.muscle_metadata, d.act, d.act_dot, d.mstate,                d.mstate_dot, d.actual_step_size, scale],        outputs=[d.act, d.mstate],    )    wp.launch(        _next_velocity,        dim=(d.nworld, m.nv),        inputs=[d.qvel, d.qacc, d.actual_step_size, scale],        outputs=[d.qvel],    )    wp.launch(        _next_position,        dim=(d.nworld, m.nbody),        inputs=[m.jnt_type, m.jnt_qposadr, m.jnt_dofadr, m.jnt_dofnum,                d.qpos, d.qvel, d.actual_step_size, scale],        outputs=[d.qpos],    )    wp.launch(        _next_time,        dim=d.nworld,        inputs=[d.time, d.actual_step_size, scale],        outputs=[d.time],    )    wp.copy(d.qacc_warmstart, d.qacc)@cache_kerneldef _tile_euler_dense(tile: TileSet):    @nested_kernel(module="unique", enable_backward=False)    def euler_dense(            # Model:            dof_damping: wp.array(dtype=float),            opt_timestep: float,            # Data in:            qM_in: wp.array3d(dtype=float),            efc_Ma_in: wp.array2d(dtype=float),            # In:            adr_in: wp.array(dtype=int),            # Out:            qacc_out: wp.array2d(dtype=float),    ):        worldid, nodeid = wp.tid()        timestep = opt_timestep        TILE_SIZE = wp.static(tile.size)        dofid = adr_in[nodeid]        M_tile = wp.tile_load(qM_in[worldid], shape=(TILE_SIZE, TILE_SIZE),                              offset=(dofid, dofid))        damping_tile = wp.tile_load(dof_damping, shape=(TILE_SIZE,),                                    offset=(dofid,))        damping_scaled = damping_tile * timestep        qm_integration_tile = wp.tile_diag_add(M_tile, damping_scaled)        Ma_tile = wp.tile_load(efc_Ma_in[worldid], shape=(TILE_SIZE,),                               offset=(dofid,))        L_tile = wp.tile_cholesky(qm_integration_tile)        qacc_tile = wp.tile_cholesky_solve(L_tile, Ma_tile)        wp.tile_store(qacc_out[worldid], qacc_tile, offset=(dofid))    return euler_dense@event_scopedef euler(m: Model, d: Data, dt: float):    """Euler integrator, semi-implicit in velocity."""    # integrate damping implicitly    qacc = wp.empty((d.nworld, m.nv), dtype=float)    for tile in m.qM_tiles:        wp.launch_tiled(            _tile_euler_dense(tile),            dim=(d.nworld, tile.adr.size),            inputs=[m.dof_damping, dt, d.qM, d.efc.Ma, tile.adr],            outputs=[qacc],            block_dim=m.block_dim.euler_dense,        )    _advance(m, d, 1.0)@event_scopedef fwd_position(m: Model, d: Data):    """ Position-dependent computations. """    smooth_pos.kinematics(m, d)    smooth_pos.com_pos(m, d)    smooth_pos.crb(m, d)    smooth_pos.factor_m(m, d)    collision_driver.collision(m, d)    constraint.make_constraint(m, d)@event_scopedef fwd_velocity(m: Model, d: Data, muscle_dynamics: bool = True):    """Velocity-dependent computations."""    smooth_vel.com_vel(m, d)    smooth_vel.site_velocity(m, d)    smooth_muscle.muscle_path(m, d)    if muscle_dynamics:        smooth_equilibrium.muscle_dynamics(m, d)@event_scopedef fwd_forces(m: Model, d: Data):    smooth_frc.passive(m, d)    smooth_frc.rne(m, d)    smooth_frc.applied_forces(m, d)    smooth_muscle.muscle_force(m, d)    if wp.static(m.opt.contact_type == ContactType.HUNT_CROSSLEY):        smooth_hunt_crossley.contact_forces(m, d)    smooth_frc.accumulate_forces(m, d)@event_scopedef fwd_acceleration(m: Model, d: Data, factorize: bool = False):    """ Compute unconstrained acceleration qacc_smooth    Args:      m: The model containing kinematic and dynamic information.      d: The data object containing the current state and output arrays.      factorize: Flag to factorize inertia matrix.    """    if factorize:        smooth_acc.factor_solve_i(m, d, d.qM, d.qLD, d.qacc_smooth,                                  d.qfrc_smooth)    else:        smooth_acc.solve_m(m, d, d.qacc_smooth, d.qfrc_smooth)@event_scopedef forward(m: Model, d: Data):    """Forward dynamics."""    fwd_position(m, d)    fwd_velocity(m, d)    fwd_forces(m, d)    fwd_acceleration(m, d, factorize=False)    wp.copy(d.qacc, d.qacc_smooth)    # fwd_acceleration(m, d, factorize=True)    # solver.solve(m, d)@event_scopedef initialize(m: Model, d: Data):    fwd_position(m, d)    fwd_velocity(m, d, muscle_dynamics=False)    smooth_equilibrium.muscle_equilibrate(m, d)    forward(m, d)@wp.kerneldef adjust_step_size(        # Data in:        time_in: wp.array(dtype=float),        next_time_in: wp.array(dtype=float),        step_size_in: wp.array(dtype=float),        integration_done: wp.array(dtype=bool),        # Data out:        actual_step_size_out: wp.array(dtype=float),        artificially_limited_out: wp.array(dtype=bool),):    worldid = wp.tid()    if integration_done[worldid]:        actual_step_size_out[worldid] = 0.0        return    if time_in[worldid] + step_size_in[worldid] >= next_time_in[worldid]:        actual_step_size_out[worldid] = wp.max(            next_time_in[worldid] - time_in[worldid], 0.0)        artificially_limited_out[worldid] = True    else:        actual_step_size_out[worldid] = step_size_in[worldid]        artificially_limited_out[worldid] = False    return@wp.kerneldef _check_done_integrating(        # Data in:        step_accepted_in: wp.array(dtype=bool),        artificially_limited_in: wp.array(dtype=bool),        # Data out:        integration_done: wp.array(dtype=bool),        nintegrating_out: wp.array(dtype=int),):    worldid = wp.tid()    if not step_accepted_in[worldid] or integration_done[worldid]:        return    # We limited the step so we wouldn't overshoot, so we're done!    if artificially_limited_in[worldid]:        integration_done[worldid] = True        wp.atomic_add(nintegrating_out, 0, -1)@wp.kerneldef _new_step_size(        # Data in:        integration_done_in: wp.array(dtype=bool),        actual_step_size_in: wp.array(dtype=float),        error_in: wp.array(dtype=float),        artificially_limited_in: wp.array(dtype=bool),        step_accepted_in: wp.array(dtype=bool),        # In:        safety: float,        min_shrink: float,        max_grow: float,        hysteresis_low: float,        hysteresis_high: float,        accuracy: float,        err_order: float,        # Data out:        step_size_out: wp.array(dtype=float),):    worldid = wp.tid()    # Done integrating, don't touch the step size    if integration_done_in[worldid]:        return    # Start with the actual step size taken    step_size = actual_step_size_in[worldid]    error = error_in[worldid]    if wp.isinf(error) or wp.isnan(error):        new_step_size = step_size * min_shrink    elif wp.abs(error) < MJ_MINVAL:        new_step_size = step_size * max_grow    else:        new_step_size = (safety * step_size *                         wp.pow(accuracy / error, 1.0 / err_order))    # If the new step is bigger than the old, don't make the change if the    #  old one was artificially limited or if the change    #  would be very small    if new_step_size > step_size:        if (artificially_limited_in[worldid] or                new_step_size < hysteresis_high * step_size):            new_step_size = step_size    # If we're supposed to shrink the step size but the one we have actually    # achieved the desired accuracy last time, we won't change the step now.    # Otherwise, if we are going to shrink the step    if new_step_size < step_size:        if step_accepted_in[worldid]:            new_step_size = step_size        else:            new_step_size = min(new_step_size, hysteresis_low * step_size)    # Keep the size change within the allowable bounds.    new_step_size = min(new_step_size, max_grow * step_size)    new_step_size = max(new_step_size, min_shrink * step_size)    step_size_out[worldid] = new_step_size    returndef _save_state(m: Model, d: Data, save_id: int, ):    @nested_kernel(module="unique", enable_backward=False)    def save_state(            # Data In:            time_in: wp.array(dtype=float),            qpos_in: wp.array2d(dtype=float),            qvel_in: wp.array2d(dtype=float),            mstate_in: wp.array2d(dtype=float),            act_in: wp.array2d(dtype=float),            # In:            sid: int,            # Out:            time_out: wp.array2d(dtype=float),            qpos_out: wp.array3d(dtype=float),            qvel_out: wp.array3d(dtype=float),            mstate_out: wp.array3d(dtype=float),            act_out: wp.array3d(dtype=float),    ):        worldid = wp.tid()        time_out[worldid, sid] = time_in[worldid]        qpos0_tile = wp.tile_load(qpos_in[worldid], shape=wp.static(m.nq))        wp.tile_store(qpos_out[worldid, sid], qpos0_tile)        qvel0_tile = wp.tile_load(qvel_in[worldid], shape=wp.static(m.nv))        wp.tile_store(qvel_out[worldid, sid], qvel0_tile)        mstate0_tile = wp.tile_load(mstate_in[worldid],                                    shape=wp.static(m.nmuscle))        wp.tile_store(mstate_out[worldid, sid], mstate0_tile)        act0_tile = wp.tile_load(act_in[worldid], shape=wp.static(m.nmuscle))        wp.tile_store(act_out[worldid, sid], act0_tile)    wp.launch_tiled(        save_state,        dim=d.nworld,        inputs=[d.time, d.qpos, d.qvel, d.mstate, d.act, save_id],        outputs=[d.integrator_state.time, d.integrator_state.qpos,                 d.integrator_state.qvel, d.integrator_state.mstate,                 d.integrator_state.act],        block_dim=m.block_dim.error_step,    )def _restore_state(m: Model, d: Data, restore_id: int, reject_only: bool):    @nested_kernel(module="unique", enable_backward=False)    def restore_state(            # Data in            time_in: wp.array2d(dtype=float),            qpos_in: wp.array3d(dtype=float),            qvel_in: wp.array3d(dtype=float),            mstate_in: wp.array3d(dtype=float),            act_in: wp.array3d(dtype=float),            step_accepted_in: wp.array(dtype=bool),            # In:            lid: int,            # Data out:            time_out: wp.array(dtype=float),            qpos_out: wp.array2d(dtype=float),            qvel_out: wp.array2d(dtype=float),            mstate_out: wp.array2d(dtype=float),            act_out: wp.array2d(dtype=float),    ):        worldid = wp.tid()        if wp.static(reject_only) and step_accepted_in[worldid]:            return        time_out[worldid] = time_in[worldid, lid]        qpos0_tile = wp.tile_load(qpos_in[worldid, lid], shape=wp.static(m.nq))        wp.tile_store(qpos_out[worldid], qpos0_tile)        qvel0_tile = wp.tile_load(qvel_in[worldid, lid], shape=wp.static(m.nv))        wp.tile_store(qvel_out[worldid], qvel0_tile)        mstate0_tile = wp.tile_load(mstate_in[worldid, lid],                                    shape=wp.static(m.nmuscle))        wp.tile_store(mstate_out[worldid], mstate0_tile)        act0_tile = wp.tile_load(act_in[worldid, lid],                                 shape=wp.static(m.nmuscle))        wp.tile_store(act_out[worldid], act0_tile)    wp.launch_tiled(        restore_state,        dim=d.nworld,        inputs=[d.integrator_state.time, d.integrator_state.qpos,                d.integrator_state.qvel, d.integrator_state.mstate,                d.integrator_state.act, d.step_accepted, restore_id],        outputs=[d.time, d.qpos, d.qvel, d.mstate, d.act],        block_dim=m.block_dim.error_step,    )def _compute_error_accept_step(m: Model, d: Data, compare_id: int):    """ Computes error with big step (assuming small step already in d) """    @nested_kernel(module="unique", enable_backward=False)    def compute_error_accept_step(            # Data in:            qpos_in: wp.array2d(dtype=float),            qvel_in: wp.array2d(dtype=float),            qpos_store_in: wp.array3d(dtype=float),            qvel_store_in: wp.array3d(dtype=float),            # In            cid: int,            accuracy: float,            # Out:            error_out: wp.array(dtype=float),            step_accepted_out: wp.array(dtype=bool),    ):        worldid = wp.tid()        error = 0.0        # Position error        nq = wp.static(m.nq)        qpos_s_tile = wp.tile_load(qpos_store_in[worldid, cid], nq)        qpos_tile = wp.tile_load(qpos_in[worldid], nq)        qdiff_tile = wp.tile_map(wp.sub, qpos_s_tile, qpos_tile)        qdiff_tile_sqr = wp.tile_map(math.sqr, qdiff_tile)        qdiff = wp.tile_sum(qdiff_tile_sqr)        error += wp.sqrt(qdiff[0]) / wp.float32(nq)        # Velocity error        nv = wp.static(m.nv)        qvel_s_tile = wp.tile_load(qvel_store_in[worldid, cid], nv)        qvel_tile = wp.tile_load(qvel_in[worldid], nv)        vdiff_tile = wp.tile_map(wp.sub, qvel_s_tile, qvel_tile)        vdiff_tile_sqr = wp.tile_map(math.sqr, vdiff_tile)        vdiff = wp.tile_sum(vdiff_tile_sqr)        error += wp.sqrt(vdiff[0]) / wp.float32(nv)        error_out[worldid] = error        step_accepted_out[worldid] = error <= accuracy    wp.launch_tiled(        compute_error_accept_step,        dim=d.nworld,        inputs=[d.qpos, d.qvel,                d.integrator_state.qpos, d.integrator_state.qvel,                compare_id, m.opt.accuracy],        outputs=[d.error, d.step_accepted],        block_dim=m.block_dim.error_step,    )@event_scopedef attempt_step(m: Model, d: Data):    # Save state y_0, note: the derivative y_0' is already available    _save_state(m, d, save_id=0)    # Adjust step size if we're overshooting    wp.launch(        adjust_step_size,        dim=d.nworld,        inputs=[d.time, d.next_time, d.step_size, d.integration_done],        outputs=[d.actual_step_size, d.artificially_limited],    )    # Big step using full current step size, store y_1    _advance(m, d, 1.0)    _save_state(m, d, save_id=1)    # Restore y_0. Note: advance doesn't modify state derivatives (except qvel),    # so we can reuse y_0'    _restore_state(m, d, restore_id=0, reject_only=False)    # Half-step 1: y_{1/2} = y_0 + dt/2 * y_0'    # Compute state derivative y_{1/2}' = f(y_{1/2})    _advance(m, d, 0.5)    forward(m, d)    # Half-step 2: y_1* = y_{1/2} + dt/2 * y_{1/2}'    _advance(m, d, 0.5)    # Compute error with y_1 from big step    _compute_error_accept_step(m, d, compare_id=1)    # If error acceptable, keep y_1, else restore y_0    _restore_state(m, d, restore_id=0, reject_only=True)    wp.launch(        _check_done_integrating,        dim=d.nworld,        inputs=[d.step_accepted, d.artificially_limited],        outputs=[d.integration_done, d.nintegrating],    )    # Compute new step size    wp.launch(        _new_step_size,        dim=d.nworld,        inputs=[            d.integration_done,            d.actual_step_size,            d.error,            d.artificially_limited,            d.step_accepted,            m.opt.safety,            m.opt.min_shrink,            m.opt.max_grow,            m.opt.hysteresis_low,            m.opt.hysteresis_high,            m.opt.accuracy,            2.0,  # err_order        ],        outputs=[d.step_size],    )    # Prepare derivatives and state for next attempt    forward(m, d)    return@wp.kerneldef _start_integrating(        # In:        dt: float,        # Data out:        next_time_out: wp.array(dtype=float),        integration_done_out: wp.array(dtype=bool),):    worldid = wp.tid()    next_time_out[worldid] += dt    integration_done_out[worldid] = False@event_scopedef step(m: Model, d: Data, dt: float):    """ Variable-step size integrator to advance by time dt """    wp.launch(        _start_integrating,        dim=d.nworld,        inputs=[dt],        outputs=[d.next_time, d.integration_done],    )    d.nintegrating.fill_(d.nworld)    wp.capture_while(        d.nintegrating,        while_body=attempt_step,        m=m,        d=d,    )@event_scopedef step_fixed(m: Model, d: Data, dt: float):    """ Variable-step size integrator to advance by time dt """    forward(m, d)    euler(m, d, dt)